function enterChapter(){let key=G.chapter===1?'foundryIntro':G.chapter===2?'citadelIntro':null;if(key&&!save.seen[key]){save.seen[key]=true;persist();dialogue(key,play)}else{play();if(G.chapter===0&&G.step===0)hint(T('firsthint'),6)}}
function chapterFinish(){const c=G.chapter;save.completed=[...new Set([...save.completed,c])];save.buttons+=G.rematch?0:35;if(c===0&&!save.unlocked.includes('kermit')){save.unlocked.push('kermit');toast(T('unlockkermit'))}if(c===1&&!save.unlocked.includes('asmon')){save.unlocked.push('asmon');toast(T('unlockasmon'))}if(c===2){save.finished=true;save.atEnding=true;save.rematch=false;save.chapter=2;save.step=CHAPTERS[2].steps.length-1;save.checkpoint=CHAPTERS[2].start;persist();endingScreen();return}save.chapter=c+1;save.step=0;save.checkpoint=CHAPTERS[c+1].start;persist();mode='modal';show(`<div class="panel chapter-card"><div class="ending-seal" style="font-size:55px;color:#9b8852">✺</div><div class="tag">${T('chaptercomplete')}</div><h2>${T(CHAPTERS[c].title)}</h2><p>${T('chapterreward')}</p>${c===0?heroImg('kermit'):heroImg('asmon')}<div class="button-row">${button(T('nextchapter'),'nextchapter')}${button(T('menu'),'title','quiet')}</div></div>`);let image=screen.querySelector('img');if(image){image.style.height='155px';image.style.maxWidth='100%'}}
function advance(){const spec=currentStep();G.encounter=false;G.cleared=true;G.triggered=false;G.marks=[];G.projectiles=[];G.anchors=[];G.hp=Math.min(maxhp(),G.hp+maxhp()*.18);G.thread=Math.min(100,G.thread+10);save.buttons+=spec.boss?12:6;G.effects.push({kind:'ring',x:G.player.x,y:G.player.y,color:'#f4d997',r:20,max:140,life:1,total:1});sfx('clear');const final=G.step===CHAPTERS[G.chapter].steps.length-1;if(!final){G.step++;G.puzzleIndex=0;save.step=G.step;if((currentStep().area||0)!==(spec.area||0)){const area=worldConfig();G.player.x=area.start[0];G.player.y=area.start[1];G.allies.forEach(a=>{a.x=G.player.x;a.y=G.player.y+12});camera.x=G.player.x;camera.y=G.player.y;G.effects=[];G.particles=[];hint(T(area.title),4)}save.checkpoint=[G.player.x,G.player.y];G.cleared=false;G.wave=0;persist()}else{save.checkpoint=CHAPTERS[G.chapter].start;persist()}
 const done=()=>final?chapterFinish():play();if(spec.story)dialogue(spec.story,done);else done()}
function currentStep(){return CHAPTERS[G.chapter].steps[G.step]}
// Navigation follows the painted paths instead of pretending every pixel is floor.
function lineDistance(x,y,ax,ay,bx,by){let dx=bx-ax,dy=by-ay,t=clamp(((x-ax)*dx+(y-ay)*dy)/(dx*dx+dy*dy||1),0,1);return Math.hypot(x-ax-t*dx,y-ay-t*dy)}
function walkable(x,y){const area=worldConfig();return !((area.blocks||[]).some(b=>Math.hypot(x-b.x,y-b.y)<b.r))&&area.floor.some(s=>s[0]==='c'?((x-s[1])/s[3])**2+((y-s[2])/s[4])**2<=1:lineDistance(x,y,s[1],s[2],s[3],s[4])<=s[5])}
function clearLine(a,b){const d=dist(a,b);for(let n=0;n<=d;n+=4){let f=d?n/d:0;if(!walkable(a.x+(b.x-a.x)*f,a.y+(b.y-a.y)*f))return false}return walkable(b.x,b.y)}
function routePoint(a,b){
 if(clearLine(a,b))return b;
 const ch=worldConfig(),ns=ch.nodes.map(p=>({x:p[0],y:p[1]})),n=ns.length;
 // Connect the current position to every visible waypoint. Choosing only the
 // nearest node causes backtracking halfway along bridges and around gears.
 const cost=ns.map(p=>clearLine(a,p)?dist(a,p):Infinity),prev=Array(n).fill(-1),seen=new Set();
 if(cost.every(c=>!Number.isFinite(c)))return ns.slice().sort((p,q)=>dist(a,p)-dist(a,q))[0];
 for(let k=0;k<n;k++){let u=-1;for(let i=0;i<n;i++)if(!seen.has(i)&&(u<0||cost[i]<cost[u]))u=i;if(u<0||!Number.isFinite(cost[u]))break;seen.add(u);for(const[l,r]of ch.edges){const v=l===u?r:r===u?l:-1;if(v>=0){const value=cost[u]+dist(ns[u],ns[v]);if(value<cost[v]){cost[v]=value;prev[v]=u}}}}
 let ends=ns.map((p,i)=>({i,visible:clearLine(p,b),d:dist(p,b)})).filter(e=>Number.isFinite(cost[e.i]));const visible=ends.filter(e=>e.visible);if(visible.length)ends=visible.sort((p,q)=>(cost[p.i]+p.d)-(cost[q.i]+q.d));else ends.sort((p,q)=>p.d-q.d);
 if(!ends.length)return b;let chain=[ends[0].i],guard=0;while(prev[chain[0]]>=0&&guard++<n)chain.unshift(prev[chain[0]]);
 while(chain.length>1&&dist(a,ns[chain[0]])<22)chain.shift();return ns[chain[0]];
}
function moveBody(body,dx,dy){if(walkable(body.x+dx,body.y+dy)){body.x+=dx;body.y+=dy;return}if(walkable(body.x+dx,body.y))body.x+=dx;if(walkable(body.x,body.y+dy))body.y+=dy}
let techHold=null;const input={x:0,y:0,attack:false,keys:new Set(),stickId:null,stickX:0,stickY:0};
function releaseInput(){techHold=null;menuTouches.clear();input.x=0;input.y=0;input.attack=false;input.keys.clear();input.stickId=null;$('#stick-knob').style.transform='';for(const e of document.querySelectorAll('#actions button'))e.classList.remove('held')}
function movement(){let x=input.x+(input.keys.has('d')||input.keys.has('arrowright')?1:0)-(input.keys.has('a')||input.keys.has('arrowleft')?1:0),y=input.y+(input.keys.has('s')||input.keys.has('arrowdown')?1:0)-(input.keys.has('w')||input.keys.has('arrowup')?1:0);let len=Math.hypot(x,y);return len>1?{x:x/len,y:y/len}:{x,y}}
const stick=$('#stick');stick.addEventListener('pointerdown',e=>{if(mode!=='play')return;e.preventDefault();audioWake();input.stickId=e.pointerId;stick.setPointerCapture(e.pointerId);stickMove(e)});function stickMove(e){if(input.stickId!==e.pointerId&&techHold?.id!==e.pointerId)return;const r=stick.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,len=Math.hypot(dx,dy),max=r.width*.32,ratio=Math.min(1,len/max);if(techHold?.id===e.pointerId){techHold.x=len?dx/len*ratio:0;techHold.y=len?dy/len*ratio:0;return}input.x=len?dx/len*ratio:0;input.y=len?dy/len*ratio:0;$('#stick-knob').style.transform=`translate(${input.x*max}px,${input.y*max}px)`}stick.addEventListener('pointermove',stickMove);function stickEnd(e){if(techHold?.id===e.pointerId)techHold=null;if(input.stickId===e.pointerId){input.stickId=null;input.x=input.y=0;$('#stick-knob').style.transform=''}}stick.addEventListener('pointerup',stickEnd);stick.addEventListener('pointercancel',stickEnd);stick.addEventListener('lostpointercapture',stickEnd);
for(const b of document.querySelectorAll('[data-act]')){b.addEventListener('pointerdown',e=>{if(mode!=='play')return;e.preventDefault();audioWake();b.setPointerCapture(e.pointerId);let a=b.dataset.act;if(a==='attack'){input.attack=true;attack()}else if(a==='dodge')dodge();else if(a==='skill')skill();else techMenu()});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>{if(b.dataset.act==='attack')input.attack=false})}
window.addEventListener('keydown',e=>{if(e.target.matches('input'))return;const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();audioWake();if(e.repeat){if(mode==='play')input.keys.add(k);return}if(mode==='dialogue'&&(k===' '||k==='enter'))return dialogueNext();if(mode==='play'){input.keys.add(k);if(k==='j')attack();if(k==='k')dodge();if(k==='l')skill();if(k===' ')techMenu();if(k==='e'||k==='enter')interact();if(['1','2','3'].includes(k))swap(+k-1);if(k==='escape'||k==='p')pause()}else if(k==='escape'){if(mode==='modal'&&screen.querySelector('[data-ui=closeoptions]'))closeOptions();else if(mode==='modal'&&screen.querySelector('[data-ui=play]'))play();else if(mode==='cinema')finishMovie()}});window.addEventListener('keyup',e=>input.keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{releaseInput();if(mode==='play')pause()});document.addEventListener('visibilitychange',()=>{releaseInput();if(document.hidden){music.pause();if(mode==='play')pause()}else if(opt.sound&&mode!=='cinema')setMusic(G.chapter)});document.addEventListener('contextmenu',e=>e.preventDefault());$('#pause').onclick=pause;$('#satchel').onclick=camp;$('#interact').onclick=interact;
// Secondary touch contacts do not synthesize click on Chromium: explicitly accept a TAP, never a scroll.
const menuTouches=new Map();let suppressMenuPointer=-1,suppressMenuUntil=0;
screen.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-ui]');if(e.pointerType==='touch'&&b)menuTouches.set(e.pointerId,{b,x:e.clientX,y:e.clientY,drag:false})});
screen.addEventListener('pointermove',e=>{const t=menuTouches.get(e.pointerId);if(t&&Math.hypot(e.clientX-t.x,e.clientY-t.y)>12)t.drag=true});
screen.addEventListener('pointercancel',e=>menuTouches.delete(e.pointerId));
screen.addEventListener('pointerup',e=>{const t=menuTouches.get(e.pointerId);menuTouches.delete(e.pointerId);if(e.pointerType==='touch'&&!e.isPrimary&&t&&!t.drag&&t.b===e.target.closest('[data-ui]')&&!t.b.disabled){e.preventDefault();suppressMenuPointer=e.pointerId;suppressMenuUntil=performance.now()+400;t.b.click()}});
screen.addEventListener('click',async e=>{if(e.isTrusted&&e.pointerId===suppressMenuPointer&&performance.now()<suppressMenuUntil)return;const b=e.target.closest('[data-ui]');if(!b||b.disabled)return;audioWake();sfx('ui');const [act,arg]=b.dataset.ui.split(':');switch(act){case'title':title();break;case'ending':endingScreen();break;case'new':confirmNew();break;case'newconfirm':await newGame();break;case'continue':await resumeGame();break;case'picker':location.href='https://joelfromschool.github.io/venice-beach-survivor/';break;case'options':openOptions();break;case'closeoptions':closeOptions();break;case'language':opt.lang=L()?'en':'ja';G.hint=0;$('#hint').classList.remove('on');saveOptions();renderOptions();updateParty();updateHud(true);break;case'sound':opt.sound=!opt.sound;saveOptions();if(opt.sound){audioWake();setMusic(G.chapter)}else music.pause();renderOptions();break;case'assist':opt.assist=!opt.assist;saveOptions();renderOptions();break;case'motion':opt.reduced=!opt.reduced;saveOptions();renderOptions();break;case'code':if($('#code').value.trim().toUpperCase()==='AMSABABY'){show(`<div class="panel"><h2>AMSABABY</h2><p>${T('cheatask')}</p>${button(T('enable'),'cheat')}${button(T('back'),'options','quiet')}</div>`)}else toast(T('wrongcode'));break;case'cheat':opt.cheat=true;saveOptions();renderOptions();break;case'uncheat':opt.cheat=false;saveOptions();renderOptions();break;case'play':play();break;case'camp':camp();break;case'rest':toast(T('healed'));play();break;case'savetitle':persist();title();break;case'slot':slot=+arg;renderCamp();break;case'hero':{const index=G.team.indexOf(arg);if(index>=0){[G.team[slot],G.team[index]]=[G.team[index],G.team[slot]]}else G.team[slot]=arg;G.active=0;persist();updateParty();renderCamp();break}case'upgrade':{let i=+arg,lv=save.gear[i],cost=20+lv*22;if(lv<3&&save.buttons>=cost){save.buttons-=cost;save.gear[i]++;G.hp=maxhp();sfx('coin');persist();renderCamp()}break}case'journal':journal();break;case'credits':endingCredits();break;case'replay':if(save?.completed.includes(+arg)){save.checkpoint=CHAPTERS[+arg].start;await loadChapter(+arg,0,true)}break;case'rematch':if(save?.finished){save.checkpoint=CHAPTERS[2].start;await loadChapter(2,CHAPTERS[2].steps.length-1,false,true)}break;case'movie':{let ret=menuReturn;playMovie(()=>ret==='title'?title():ret==='ending'?endingScreen():play());break}case'skipmovie':finishMovie();break;case'dialoguenext':dialogueNext();break;case'chapterstart':enterChapter();break;case'nextchapter':await loadChapter(save.chapter,0,true);break;case'tech':useTech(arg,false);break;case'triple':useTech(arg,true);break;case'retry':await resumeGame();break;case'assistretry':opt.assist=true;saveOptions();await resumeGame();break}});
function swap(i){if(mode!=='play'||i===G.active)return;G.active=i;G.attackCD=Math.max(G.attackCD,.15);G.invuln=Math.max(G.invuln,.18);updateParty();sfx('ui');burst(G.player.x,G.player.y-35,HERO[G.team[i]].color,10)}
function updateParty(){if(!save)return;$('#party').innerHTML=G.team.map((id,i)=>`<button class="${i===G.active?'active':''}" data-slot="${i}" aria-label="${esc(name(id))}">${heroImg(id)}<span>${name(id)}</span><i></i></button>`).join('');for(const b of document.querySelectorAll('#party button'))b.onclick=()=>swap(+b.dataset.slot)}
function hint(text,seconds=4){$('#hint').textContent=text;$('#hint').classList.add('on');G.hint=seconds}
function updateHud(force=false){if(!force&&time-lastHud<.09)return;lastHud=time;const id=G.team[G.active],h=HERO[id];$('#chapter-label').textContent=T(CHAPTERS[G.chapter].title)+(opt.cheat?' · AMSABABY':'');$('#health-fill').style.width=clamp(G.hp/maxhp()*100,0,100)+'%';$('#health-text').textContent=`${Math.ceil(G.hp)} / ${maxhp()}${G.shield>0?' + '+Math.ceil(G.shield):''}`;let spec=currentStep(),target=objectivePoint();$('#objective-text').textContent=spec.points&&G.cleared?T('spoolcount',{n:G.puzzleIndex}):G.anchors.length&&!G.anchors.every(a=>a.done)?T('anchors',{n:G.anchors.filter(a=>a.done).length}):loc(spec.text);let d=dist(G.player,target),p=routePoint(G.player,target),ang=Math.atan2(p.y-G.player.y,p.x-G.player.x);const arrows=['→','↘','↓','↙','←','↖','↑','↗'];$('#objective-distance').textContent=d<65?'✦ '+T('nearby'):arrows[(Math.round(ang/(Math.PI/4))+8)%8]+' '+T('steps',{n:Math.max(1,Math.round(d/12))});$('#objective-distance').title=T('routehelp');let boss=G.enemies.find(e=>e.boss);$('#boss-ui').hidden=!boss;if(boss){$('#boss-name').textContent=T(boss.id==='asmon'?'asmonboss':boss.id)+(boss.phase>1||boss.id==='unraveler'?' · '+T('phase',{n:boss.phase}):'');$('#boss-state').textContent=boss.recover>0?T('openseam'):boss.tell>0?T(boss.moveKey)+' · '+boss.tell.toFixed(1)+(L()?'秒':'s'):boss.charge?T(boss.moveKey):T('bosswatch');$('#boss-state').classList.toggle('open',boss.recover>0);$('#boss-fill').style.width=Math.max(0,boss.hp/boss.maxhp*100)+'%'}$('#thread i').style.width=G.thread+'%';$('#thread span').textContent=G.thread>=100?T('ready'):Math.floor(G.thread)+' / 100 '+T('thread');$('#attack span').textContent=T('attack');$('#dodge span').textContent=T('dodge')+' '+G.dodge;$('#skill span').textContent=G.skillCD[id]>0?Math.ceil(G.skillCD[id])+(L()?'秒':'s'):T('skill');$('#team span').textContent=T('team');$('#move-label').textContent=T('move');$('#skill').classList.toggle('cooldown',G.skillCD[id]>0);$('#dodge').classList.toggle('cooldown',G.dodge===0);$('#team').classList.toggle('cooldown',G.thread<50);document.querySelectorAll('#party button i').forEach((e,i)=>{let id=G.team[i];e.style.width=(1-clamp((G.skillCD[id]||0)/HERO[id].skill,0,1))*58+'px'});const item=interactable();G.lastInteract=item;$('#interact').hidden=!item;if(item)$('#interact').textContent=T(item.kind==='anchor'?'repair':item.kind==='chest'?'chest':item.kind==='camp'?'campfire':spec.type==='gate'?'enter':spec.points?'weavespool':spec.type==='valve'?'valve':'collect')}
function nearestEnemy(range=Infinity,origin=G.player){let best=null,d=range;for(const e of G.enemies)if(!e.dead&&dist(e,origin)<d){best=e;d=dist(e,origin)}return best}
function burst(x,y,color,n=12){if(opt.reduced)n=Math.min(n,6);for(let i=0;i<n&&G.particles.length<180;i++)G.particles.push({x,y,vx:rnd(-90,90),vy:rnd(-130,50),life:rnd(.25,.65),color,r:rnd(1.5,3.5)})}
function floatText(x,y,text,color='#fff0c5'){G.texts.push({x,y,text:String(text),color,life:.9});if(G.texts.length>24)G.texts.shift()}
function hurtEnemy(e,amount,color='#ffe6a6',root=0){if(e.dead)return;if(e.id==='unraveler'&&e.phase===3&&G.anchors.some(a=>!a.done)){if(e.shieldText<=0||!e.shieldText){floatText(e.x,e.y-90,'◇','#dbb4ef');e.shieldText=1}return}let damage=amount*power()*(e.boss&&e.recover>0?1.2:1);if(e.boss&&e.recover>0)G.metrics.recoveryHits++;let hp=e.hp-damage;if(e.id==='unraveler'){if(e.phase===1)hp=Math.max(hp,e.maxhp*.66);if(e.phase===2)hp=Math.max(hp,e.maxhp*.33)}e.hp=hp;e.flash=.1;e.root=Math.max(e.root||0,root*(e.boss?.35:1));G.thread=clamp(G.thread+Math.min(3.3,damage*.045)*ribbon(),0,100);floatText(e.x+rnd(-12,12),e.y-e.size*.65,Math.round(damage),color);burst(e.x,e.y-e.size*.45,color,5);if(!opt.reduced)shake=Math.max(shake,1.6);if(e.hp<=0){e.dead=true;save.totalKills++;save.buttons+=e.boss?0:1;burst(e.x,e.y-e.size*.5,'#e8d18b',18);if(e.boss){for(const other of G.enemies)other.dead=true;G.projectiles=[];G.marks=[];G.anchors=[];sfx('clear')}}}
function hurtPlayer(amount){if(amount<=0)return;if(G.invuln>0||opt.cheat||mode!=='play')return;let n=amount*(opt.assist?.55:1);let absorbed=Math.min(G.shield,n);G.shield-=absorbed;n-=absorbed;G.hp=Math.max(0,G.hp-n);G.metrics.damage+=n;G.invuln=.85;G.effects.push({kind:'hurt',life:.4,total:.4});sfx('hurt');if(!opt.reduced)shake=5;floatText(G.player.x,G.player.y-90,'−'+Math.round(n),'#ffb2a8');if(G.hp<maxhp()*.3&&G.hp>0)hint(T('lowhp'),3);if(G.hp<=0)defeat()}
function attack(){if(mode!=='play'||G.attackCD>0)return;const id=G.team[G.active],h=HERO[id],target=nearestEnemy(h.range+30);G.attackCD=h.rate;G.player.anim=.2;if(target)G.player.face=Math.atan2(target.y-G.player.y,target.x-G.player.x);sfx('attack');const x=G.player.x,y=G.player.y;if(id==='bean'||id==='kermit'){if(target){fire(x,y-22,target.x,target.y-target.size*.35,h.damage,h.color,false,id==='bean'?'pea':'note')}else fire(x,y-22,x+Math.cos(G.player.face)*250,y-22+Math.sin(G.player.face)*250,h.damage,h.color,false,id==='bean'?'pea':'note')}
 else{G.effects.push({kind:'slash',x,y:y-24,angle:G.player.face,r:h.range,color:h.color,life:.22,total:.22});for(const e of G.enemies){const ang=Math.atan2(e.y-y,e.x-x),diff=Math.atan2(Math.sin(ang-G.player.face),Math.cos(ang-G.player.face));if(dist(e,G.player)<h.range+e.size*.18&&(Math.abs(diff)<(id==='pooh'?1.4:1.15)||dist(e,G.player)<48))hurtEnemy(e,h.damage,h.color)}}}
function dodge(){if(mode!=='play'||G.dodge<=0)return;const m=movement(),len=Math.hypot(m.x,m.y);G.dodge--;G.dodgeCD=G.dodgeCD||dodgeRecovery();G.dash=.26;G.dashX=len?m.x/len:Math.cos(G.player.face);G.dashY=len?m.y/len:Math.sin(G.player.face);G.invuln=Math.max(G.invuln,.5);G.dodgeWindow=.5;G.perfectReady=true;G.effects.push({kind:'ring',x:G.player.x,y:G.player.y-10,r:10,max:60,color:HERO[G.team[G.active]].color,life:.3,total:.3});sfx('dodge')}
function dodgeRecovery(){return save.chests.includes(1)?2.2:2.5}
function perfectDodge(){if(G.dodgeWindow<=0||!G.perfectReady)return;G.perfectReady=false;G.metrics.perfect++;G.thread=Math.min(100,G.thread+12*ribbon());for(const id of G.team)G.skillCD[id]=Math.max(0,(G.skillCD[id]||0)-.6);floatText(G.player.x,G.player.y-115,T('perfectstitch'),'#fff0a0');G.effects.push({kind:'ring',x:G.player.x,y:G.player.y,r:20,max:80,color:'#fff0a0',life:.45,total:.45});sfx('coin')}
function skill(){if(mode!=='play')return;const id=G.team[G.active];if((G.skillCD[id]||0)>0)return;G.skillCD[id]=HERO[id].skill/ribbon();floatText(G.player.x,G.player.y-115,loc(HERO[id].skillName),HERO[id].color);G.effects.push({kind:'sigil',id,x:G.player.x,y:G.player.y-20,color:HERO[id].color,life:.7,total:.7});G.player.anim=.4;const x=G.player.x,y=G.player.y,color=HERO[id].color;G.invuln=Math.max(G.invuln,id==='asmon'?1.8:.75);let damage=75,range=190,root=0,heal=0;if(id==='pooh'){damage=56;range=200;heal=18;G.shield=Math.min(45,G.shield+22)}if(id==='bean'){damage=65;range=240;root=3;heal=8}if(id==='kermit'){damage=55;range=260;heal=30;root=1.6}if(id==='asmon'){damage=100;G.shield=Math.min(45,G.shield+15)}G.hp=Math.min(maxhp(),G.hp+heal);if(heal)floatText(x,y-100,'+'+heal,'#bde1a2');for(const e of G.enemies)if(dist(e,G.player)<range){hurtEnemy(e,damage,color,root);if(id==='pooh'&&!e.boss&&!e.dead){const a=dist(e,G.player)>.1?Math.atan2(e.y-y,e.x-x):G.player.face;e.knockback={vx:Math.cos(a)*260,vy:Math.sin(a)*260,life:.2};e.root=Math.max(e.root,.24)}}G.effects.push({kind:'ring',x,y:y-12,r:20,max:range,color,life:.65,total:.65});burst(x,y-25,color,24);sfx('skill')}
function useTech(key,triple){const recipe=(triple?TRIPLES:TECH)[key],cost=triple?100:50;if(!recipe||G.thread<cost)return;play();G.thread-=cost;const targets=G.enemies.filter(e=>dist(e,G.player)<recipe.range+e.size*.25);G.invuln=Math.max(G.invuln,1.3);G.hp=Math.min(maxhp(),G.hp+(recipe.heal||0));G.shield=Math.min(55,G.shield+(recipe.guard||0)*10);if(recipe.refresh)for(const id of G.team)G.skillCD[id]=0;for(const e of targets)hurtEnemy(e,recipe.power,recipe.color,recipe.root||0);G.techAnim={life:1.4,total:1.4,color:recipe.color,name:loc(recipe.name),triple,ids:key.split('+'),x:G.player.x,y:G.player.y};for(let i=0;i<(triple?3:2);i++)G.effects.push({kind:'ring',x:G.player.x,y:G.player.y-20,r:25+i*15,max:recipe.range-i*22,color:triple?[HERO[G.team[0]].color,HERO[G.team[1]].color,HERO[G.team[2]].color][i]:recipe.color,life:1-i*.12,total:1-i*.12});burst(G.player.x,G.player.y-30,recipe.color,triple?40:25);sfx('tech');if(!targets.length)toast(T('tryhold'))}
function fire(x,y,tx,ty,damage,color,enemy=false,kind='orb',speed=330){if(G.projectiles.length>=80)return;let a=Math.atan2(ty-y,tx-x);G.projectiles.push({x,y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,life:2,damage,color,enemy,kind,r:kind==='pea'?7:6,target:kind==='note'&&!enemy?nearestEnemy(500,{x,y}):null})}
function objectivePoint(){const a=G.anchors.find(a=>!a.done);if(a)return a;const s=currentStep();if(s.points&&G.cleared){const p=s.points[G.puzzleIndex||0];return{x:p[0],y:p[1]}}return{x:s.p[0],y:s.p[1]}}
function interactable(){if(mode!=='play')return null;const p=G.player,ch=worldConfig();const anchor=G.anchors.find(a=>!a.done&&dist(a,p)<64);if(anchor)return{kind:'anchor',obj:anchor};if(ch.chest&&!G.encounter&&!save.chests.includes(G.chapter)&&Math.hypot(p.x-ch.chest[0],p.y-ch.chest[1])<70)return{kind:'chest'};if(!G.encounter&&G.triggered&&G.cleared&&dist(p,objectivePoint())<75)return{kind:'objective'};if(!G.encounter&&Math.hypot(p.x-ch.start[0],p.y-ch.start[1])<65)return{kind:'camp'};return null}
function interact(){const item=interactable();if(!item)return;if(item.kind==='camp')return camp();if(item.kind==='chest'){save.chests=[...new Set([...save.chests,G.chapter])];save.buttons+=18;G.hp=Math.min(maxhp(),G.hp+45);persist();sfx('coin');toast(T('relicfound',{name:loc(RELICS[G.chapter].name),effect:loc(RELICS[G.chapter].effect)}));burst(G.player.x,G.player.y-50,'#f3d484',30)}else if(item.kind==='anchor'){item.obj.done=true;G.invuln=Math.max(G.invuln,1);G.hp=Math.min(maxhp(),G.hp+12);G.thread=Math.min(100,G.thread+18);burst(item.obj.x,item.obj.y-20,'#edcc8d',22);sfx('coin');if(G.anchors.every(a=>a.done)){toast(T('vulnerable'));const b=G.enemies.find(e=>e.id==='unraveler');if(b){b.root=2.5;b.cool=3;b.tell=0;b.commit=0;b.actions=[];b.charge=null;b.recoverDelay=0;b.recover=2.5;G.marks=[];G.projectiles=G.projectiles.filter(p=>!p.enemy)}}}else{if(currentStep().points&&G.puzzleIndex<2){G.puzzleIndex++;G.hp=Math.min(maxhp(),G.hp+10);sfx('coin');burst(G.player.x,G.player.y-30,'#e9cc87',15);toast(T('spoolcount',{n:G.puzzleIndex}));return}toast(T(currentStep().type==='valve'?'valveturned':'stitchcollected'));advance()}}
function spawnPoint(center,index=0){for(let n=0;n<60;n++){let a=rnd(0,Math.PI*2),r=rnd(48,105),p={x:center[0]+Math.cos(a)*r,y:center[1]+Math.sin(a)*r};if(walkable(p.x,p.y)&&dist(p,G.player)>62)return p}return{x:center[0]+index*8,y:center[1]}}
function spawnEnemy(id,pos,boss=false){const config={beetle:[105,53,8],spool:[115,42,9],wisp:[95,49,8],mouse:[145,62,11],bramble:[1150,38,19],tollkeeper:[1400,33,21],asmon:[1250,55,20],unraveler:[2500,23,23]}[id],m=1+G.chapter*.1;const e={id,x:pos.x,y:pos.y,hp:config[0]*(boss?(G.rematch?1.25:1):(1+G.chapter*.1)),maxhp:config[0]*(boss?(G.rematch?1.25:1):(1+G.chapter*.1)),speed:config[1],damage:config[2]*m*(boss&&G.rematch?1.25:1),boss,size:boss?(id==='unraveler'?176:id==='asmon'?114:148):(id==='wisp'?64:66),cool:boss?1.4:rnd(.6,1.5),root:0,flash:0,phase:1,pattern:0,dead:false,anim:rnd(0,10),nav:null,navCD:0,shieldText:0,tell:0,commit:0,recover:0,recoverDelay:0,recoverFor:0,actions:[],charge:null,moveKey:''};G.enemies.push(e);return e}
function beginEncounter(){if(G.triggered)return;G.triggered=true;G.cleared=false;const spec=currentStep(),start=()=>{G.encounter=spec.type!=='gate';G.wave=0;G.cleared=spec.type==='gate';if(spec.boss)spawnEnemy(spec.boss,{x:spec.p[0],y:spec.p[1]},true);else spec.enemies.forEach((id,i)=>spawnEnemy(id,spawnPoint(spec.p,i)));if(spec.type!=='gate'){if(save.chests.includes(2))G.thread=Math.min(100,G.thread+15);toast(T('encounter'))}if(mode!=='play')play();else updateHud(true)};if(spec.before&&!save.seen[`${G.chapter}-${G.step}-before`]){save.seen[`${G.chapter}-${G.step}-before`]=true;persist();dialogue(spec.before,start)}else start()}
function defeat(){mode='modal';G.encounter=false;releaseInput();persist();show(`<div class="panel chapter-card"><div class="tag">${T(CHAPTERS[G.chapter].title)}</div><h2>${T('defeat')}</h2><p>${T('defeatbody')}</p><div class="title-buttons">${button(T('retry'),'retry')}${!opt.assist?button(T('assist'),'assistretry','secondary'):''}${button(T('menu'),'title','quiet')}</div></div>`)}
function markCircle(x,y,r,life,damage,color='#c96457'){G.marks.push({shape:'circle',x,y,r,life,total:life,damage,color})}
function markLine(ax,ay,bx,by,r,life,damage,color='#c96457'){G.marks.push({shape:'line',ax,ay,bx,by,r,life,total:life,damage,color})}
function markHit(m,p,pad=0){return m.shape==='circle'?Math.hypot(p.x-m.x,p.y-m.y)<m.r+pad:lineDistance(p.x,p.y,m.ax,m.ay,m.bx,m.by)<m.r+pad}
function bossMove(e,key,wind,recovery=1){e.moveKey=key;e.tell=wind;e.commit=wind+.5;e.recover=0;e.recoverDelay=wind+.5;e.recoverFor=recovery;e.cool=wind+.5+recovery+.45;G.metrics.moves[key]=(G.metrics.moves[key]||0)+1}
function safeCharge(e,p,length=180){const a=Math.atan2(p.y-e.y,p.x-e.x);let end={x:e.x,y:e.y};for(let d=5;d<=length;d+=5){const q={x:e.x+Math.cos(a)*d,y:e.y+Math.sin(a)*d};if(!walkable(q.x,q.y)||!clearLine(e,q))break;end=q}return end}
function planCharge(e,target,wind){const end=safeCharge(e,target,Math.min(210,dist(e,target)+45));markLine(e.x,e.y,end.x,end.y,34,wind,e.damage*1.1);e.actions.push({kind:'charge',delay:wind,tx:end.x,ty:end.y})}
