function drawBeacon(x,y,symbol,color){ctx.save();ctx.strokeStyle=color;ctx.globalAlpha=.55+.2*Math.sin(time*3);ctx.lineWidth=2;ctx.setLineDash([4,5]);ctx.beginPath();ctx.ellipse(x,y,25+Math.sin(time*2)*3,13,0,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=.95;ctx.fillStyle='#254d40cc';ctx.beginPath();ctx.arc(x,y-50+Math.sin(time*2)*3,18,0,Math.PI*2);ctx.fill();ctx.strokeStyle=color;ctx.stroke();ctx.fillStyle=color;ctx.font='23px Georgia';ctx.textAlign='center';ctx.fillText(symbol,x,y-42+Math.sin(time*2)*3);ctx.restore()}
