function drawActors(){let actors=G.enemies.map(e=>({kind:'enemy',y:e.y,obj:e}));const others=G.team.filter((_,i)=>i!==G.active);for(let i=0;i<2;i++)actors.push({kind:'ally',y:G.allies[i].y,obj:G.allies[i],id:others[i]});actors.push({kind:'player',y:G.player.y,obj:G.player,id:G.team[G.active]});actors.sort((a,b)=>a.kind==='player'?1:b.kind==='player'?-1:a.y-b.y);for(const a of actors){const o=a.obj;if(a.kind==='enemy'){let bob=o.id==='wisp'?Math.sin(time*2+o.anim)*6:Math.sin(time*6+o.anim)*1.7;groundShadow(o.x,o.y,o.size*.29);if(o.boss&&o.recover>0){ctx.strokeStyle='#f9dfa0';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(o.x,o.y,42,17,0,0,Math.PI*2);ctx.stroke()}drawSprite(o.id,o.x,o.y-bob,o.size,{flip:o.x>G.player.x,flash:o.flash>0,rotation:Math.sin(time*4+o.anim)*.015});if(!o.boss&&o.hp<o.maxhp){ctx.fillStyle='#183a2ed0';rounded(o.x-22,o.y-o.size-9,44,4,2);ctx.fill();ctx.fillStyle='#edbc90';rounded(o.x-22,o.y-o.size-9,44*o.hp/o.maxhp,4,2);ctx.fill()}if(o.root>0){ctx.strokeStyle='#b7cb9a';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(o.x,o.y,27,10,time,0,Math.PI*2);ctx.stroke()}if(o.id==='unraveler'&&o.phase===3&&G.anchors.some(a=>!a.done)){ctx.strokeStyle='#d3b6d499';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(o.x,o.y-o.size*.4,105,95,0,0,Math.PI*2);ctx.stroke()}}
 else{const active=a.kind==='player',moving=active?Math.hypot(movement().x,movement().y)>.1:dist(o,G.player)>55,h=active?98:77;let bob=Math.sin(time*(moving?12:2.7)+(active?0:2))* (moving?2:1.6);groundShadow(o.x,o.y,active?25:19,active?.25:.16);if(active){ctx.strokeStyle=HERO[a.id].color;ctx.lineWidth=2.5;ctx.beginPath();ctx.ellipse(o.x,o.y,28,12,0,0,Math.PI*2);ctx.stroke();if(G.shield>0){ctx.strokeStyle='#ecd38a88';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(o.x,o.y-40,45,58,0,0,Math.PI*2);ctx.stroke()}}let alpha=active&&G.invuln>0&&Math.floor(time*15)%2===0?.6:active?1:.87;drawSprite(a.id,o.x,o.y-bob,h,{alpha,flip:Math.cos(G.player.face)<-.2,rotation:moving?Math.sin(time*10)*.025:0});if(active){ctx.fillStyle='#fff0c5';ctx.font='bold 11px system-ui';ctx.textAlign='center';ctx.shadowColor='#16352b';ctx.shadowBlur=3;ctx.fillText(name(a.id),o.x,o.y+19);ctx.shadowBlur=0;ctx.beginPath();ctx.moveTo(o.x,o.y-h-7);ctx.lineTo(o.x-5,o.y-h-15);ctx.lineTo(o.x+5,o.y-h-15);ctx.closePath();ctx.fill()}}}}
